/**
 * Ardent design tokens, framework neutral. Part of the Ardent design kit: the
 * one place the look is defined. Ardent Core gets them as CSS variables
 * (kit/ardent.css, generated by `npm run kit` in engine/) and Ardent Field
 * imports them directly. Change them here and both apps follow.
 */

export const color = {
  /** Page background. */
  bg: '#070707',
  /** Panels and cards. */
  surface: '#121212',
  /** Recessed wells inside a panel. */
  inset: '#0b0b0b',
  /** Controls, chips, hovered rows. */
  raised: '#1d1d1d',
  /** Dividers between table rows only. Cards, panels and buttons never take a border. */
  line: '#1c1c1c',
  lineStrong: '#2e2e2e',
  fg: '#f2f2f2',
  fgMuted: '#9a9a9a',
  fgFaint: '#5f5f5f',
  /** The one brand accent. Use sparingly: active state, primary signal, live things. */
  ember: '#ff6a1a',
  emberSoft: 'rgba(255, 106, 26, 0.15)',
  /** Status colours. Only for state, never decoration. */
  ok: '#22c55e',
  warn: '#f59e0b',
  danger: '#ef4444',
  info: '#3b82f6',
  violet: '#8b5cf6',
} as const

export const radius = {
  sm: 6,
  md: 8,
  lg: 10,
  xl: 14,
  pill: 999,
} as const

/** 4pt grid. */
export const space = {
  0: 0,
  1: 4,
  1.5: 6,
  2: 8,
  3: 12,
  4: 16,
  5: 20,
  6: 24,
  8: 32,
  10: 40,
  12: 48,
} as const

export const font = {
  /** Wordmark, hero lines and big screen titles. Wide, uppercase, tracked out. */
  display: 'Michroma',
  /** Everything else. */
  body: 'Geist',
  /** Every number, money value, job ref, postcode and registration. */
  mono: 'Geist Mono',
} as const

export const type = {
  caption: { size: 11, lineHeight: 14 },
  small: { size: 12, lineHeight: 16 },
  body: { size: 13, lineHeight: 18 },
  bodyLarge: { size: 15, lineHeight: 22 },
  title: { size: 18, lineHeight: 24 },
  metric: { size: 28, lineHeight: 32 },
  display: { size: 32, lineHeight: 36, letterSpacing: 1.5 },
} as const

/** Calm, eased motion; only real wins get a spring. */
export const motion = {
  /** Content arriving: fades and short slides. */
  enter: 400,
  /** The light (bloom) changing with the working mode. */
  light: 900,
  /** Gap between items arriving down a list. */
  stagger: 45,
  /** How long a hold-to-commit takes. */
  hold: 900,
  ease: 'cubic-bezier(0.22, 1, 0.36, 1)',
} as const

/** The bloom behind the content follows what the operator is doing. */
export const bloom = {
  on_site: { color: '#ff6a1a', strength: 0.22 },
  en_route: { color: '#7d93ad', strength: 0.18 },
  workshop: { color: '#b08a5a', strength: 0.14 },
  on_call: { color: '#9a9a9a', strength: 0.1 },
  delayed: { color: '#f59e0b', strength: 0.16 },
  off_shift: { color: '#5f5f5f', strength: 0.06 },
} as const

export const tokens = { color, radius, space, font, type, motion, bloom } as const
export type Tokens = typeof tokens
